]$data$::jsonb)
      as item(slug text, title text, excerpt text, category text, content text)
  )
  update public.posts as posts
  set title = updates.title,
      excerpt = updates.excerpt,
      category = updates.category,
      content = updates.content
  from updates
  where posts.slug = updates.slug
    and posts.published = true;

  get diagnostics affected_count = row_count;
  if affected_count <> 16 then
    raise exception 'Expected 16 published regional pages, updated %', affected_count;
  end if;
end;
$migration$;
